  const holders = plan.units.filter(unit => unit.owned.includes('big.json'));
  assert.ok(holders.length >= 5);
  assert.deepEqual(holders.map(unit => unit.parts['big.json']), holders.map((_, index) => ({index, count: holders.length})));
